public String getType(){
  try {
    String cssClass = alertRoot.getAttribute("class");
    Matcher classMatcher = Pattern.compile("alert-(.+)").matcher(cssClass);
    if (!classMatcher.find()) {
      throw new RuntimeException("Failed to identify feedback message type");
    }
    return classMatcher.group(1);
  } catch (RuntimeException e) {
    // Log the exception and return a default value or rethrow as needed
    System.err.println("Error identifying feedback message type: " + e.getMessage());
    return "unknown"; // Default value in case of error
  }
}
